package com.example.telegramconnector.service;
import com.example.telegramconnector.domain.TelegramChatChannel; import com.example.telegramconnector.repository.TelegramChatChannelRepository; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service; import java.util.*;
@Service public class TelegramChatChannelService { private final TelegramChatChannelRepository repo; public TelegramChatChannelService(TelegramChatChannelRepository r){repo=r;} public TelegramChatChannel resolve(Long chatId,String botChannelId){return repo.findByTelegramChatIdAndBotChannelId(chatId,botChannelId).orElseGet(()->create(chatId,botChannelId));} public TelegramChatChannel byId(String id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Unknown channelId: "+id));} private TelegramChatChannel create(Long chatId,String bot){try{return repo.save(new TelegramChatChannel(UUID.randomUUID().toString(),chatId,bot));}catch(DataIntegrityViolationException e){return repo.findByTelegramChatIdAndBotChannelId(chatId,bot).orElseThrow(()->e);}} }
